#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# The one-time cutover to the beta channel (beta-channel spec, archived in .scratch/ at 2ada153, ticket 04;
# why in docs/adr/0002-beta-branch-with-semantic-release.md). Run it from the repo root,
# signed in with `gh auth login` as a repository admin, after the beta-channel tickets
# 01–03 have merged:
#
#   bash scripts/cutover-beta.sh
#
# Every stage checks the current state first and skips what is already done, so it is safe
# to stop and run again. Settings changes are made with `gh api` after a y/N confirmation;
# the two outside GitHub (npm, Cloudflare) open the page and wait for you.

REPO="chalharb/archidocs"

# done_ "msg" reports a check that passed.
done_() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }

# need_gh stops unless gh is signed in with admin rights here: every stage uses it.
need_gh() {
  if ! command -v gh >/dev/null 2>&1 || ! gh auth status >/dev/null 2>&1; then
    warn "gh is not installed or not signed in. Run: gh auth login"; exit 1
  fi
  if ! command -v jq >/dev/null 2>&1; then
    warn "jq is not installed. Install it (brew install jq) and run again."; exit 1
  fi
  if [[ "$(gh api "repos/$REPO" -q .permissions.admin)" != "true" ]]; then
    warn "Your gh account isn't an admin of $REPO; the settings below need one."; exit 1
  fi
}

# main_ruleset_id prints the id of the ruleset named "main".
main_ruleset_id() { gh api "repos/$REPO/rulesets" -q '.[] | select(.name == "main") | .id'; }

run_wizard() {

TOTAL_STAGES=10

banner "Cut over to the beta channel"
need_gh

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check the starting point"
say "The cutover starts from a clean stable release with semantic-release in place."
fail=0
if git ls-remote --exit-code --tags origin refs/tags/v1.3.2 >/dev/null 2>&1; then done_ "v1.3.2 is tagged"; else warn "v1.3.2 isn't tagged on origin"; fail=1; fi
if gh api "repos/$REPO/contents/release.config.mjs?ref=main" --silent 2>/dev/null; then done_ "semantic-release is on main (ticket 01)"; else warn "release.config.mjs isn't on main: merge ticket 01 first"; fail=1; fi
if [[ -z "$(gh pr list -R "$REPO" --state open --search 'chore(main): release in:title' --json number -q '.[].number')" ]]; then done_ "no release-please PR is open"; else warn "a release-please PR is still open: close it"; fail=1; fi
if gh secret list -R "$REPO" | grep -q '^RELEASE_TOKEN'; then
  done_ "RELEASE_TOKEN is set"
else
  warn "RELEASE_TOKEN isn't set. The release job needs it to push the release commit and open PRs."
  open_url "https://github.com/settings/personal-access-tokens/new"
  step "Fine-grained token, resource owner chalharb, only this repository."
  step "Permissions: Contents → Read and write, Pull requests → Read and write. Generate, then copy it."
  ask_secret RELEASE_TOKEN "Paste the token:"
  set_secret RELEASE_TOKEN "$RELEASE_TOKEN"
fi
if gh secret list -R "$REPO" | grep -q '^RELEASE_PLEASE_TOKEN'; then
  if confirm "RELEASE_PLEASE_TOKEN is no longer used. Delete it?"; then gh secret delete RELEASE_PLEASE_TOKEN -R "$REPO"; done_ "deleted RELEASE_PLEASE_TOKEN"; fi
fi
(( fail )) && { warn "Fix the items above, then run the wizard again."; exit 1; }
pause "Press Enter to continue."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Allow merge commits"
say "Promotions (beta → main) and back-merges (main → beta) must be merge commits."
say "Today the repo allows only squash merges. Feature PRs will stay squash-merged."
if [[ "$(gh api "repos/$REPO" -q .allow_merge_commit)" == "true" ]]; then
  done_ "merge commits are already allowed"
elif confirm "Allow merge commits on $REPO (squash stays allowed)?"; then
  gh api -X PATCH "repos/$REPO" -F allow_merge_commit=true -F allow_squash_merge=true --silent
  done_ "merge commits allowed"
else
  SKIPPED+=("Allow merge commits: Settings → General → Pull Requests")
fi
pause "Press Enter to continue."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Rework the main ruleset"
say "The ruleset named \"main\" targets the default branch, which is about to become beta."
say "This pins it to refs/heads/main, then for main:"
step "drops \"Require linear history\", which blocks the promotion's merge commit"
step "allows only merge commits (promotions and hotfix PRs alike)"
step "lets repository admins bypass, so the release job (RELEASE_TOKEN) can push"
note "    chore(release): X.Y.Z [skip ci] and the version tag"
id=$(main_ruleset_id)
if [[ -z "$id" ]]; then
  warn "No ruleset named \"main\". Set this up by hand under Settings → Rules."
  SKIPPED+=("main ruleset: pin to main, drop linear history, merge only, admin bypass")
else
  current=$(gh api "repos/$REPO/rulesets/$id")
  updated=$(jq '{name, target, enforcement,
      conditions: {ref_name: {include: ["refs/heads/main"], exclude: []}},
      bypass_actors: [{actor_id: 5, actor_type: "RepositoryRole", bypass_mode: "always"}],
      rules: [.rules[]
        | select(.type != "required_linear_history")
        | if .type == "pull_request" then .parameters.allowed_merge_methods = ["merge"] else . end]}' <<<"$current")
  if [[ "$(jq -S . <<<"$updated")" == "$(jq -S '{name, target, enforcement, conditions, bypass_actors, rules}' <<<"$current")" ]]; then
    done_ "the main ruleset is already set up"
  else
    note "New ruleset:"; jq -c '{conditions, bypass_actors, rules: [.rules[].type], merge: (.rules[] | select(.type == "pull_request") | .parameters.allowed_merge_methods)}' <<<"$updated" | sed 's/^/    /'
    if confirm "Apply it?"; then
      gh api -X PUT "repos/$REPO/rulesets/$id" --input - --silent <<<"$updated"
      done_ "main ruleset updated"
    else
      SKIPPED+=("main ruleset: pin to main, drop linear history, merge only, admin bypass")
    fi
  fi
fi
pause "Press Enter to continue."

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Create the beta branch"
say "beta starts at main's tip. Unreleased work lands there from now on."
if gh api "repos/$REPO/branches/beta" --silent 2>/dev/null; then
  done_ "beta already exists"
elif confirm "Create beta from main?"; then
  sha=$(gh api "repos/$REPO/git/ref/heads/main" -q .object.sha)
  gh api -X POST "repos/$REPO/git/refs" -f ref=refs/heads/beta -f sha="$sha" --silent
  done_ "created beta at ${sha:0:7}"
else
  warn "The stages after this one need beta. Run the wizard again when you're ready."; exit 1
fi
note "Creating it counts as a push to beta: the Release run finds nothing new since v1.3.2 and"
note "publishes nothing, and the Sites run deploys the three beta. sites for the first time."
pause "Press Enter to continue."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Protect beta"
say "A \"beta\" ruleset: pull requests required, squash for features and merge for the"
say "back-merge from main, the same status checks as main, no deletes or force-pushes."
if [[ -n "$(gh api "repos/$REPO/rulesets" -q '.[] | select(.name == "beta") | .id')" ]]; then
  done_ "a beta ruleset already exists"
elif confirm "Create the beta ruleset?"; then
  id=$(main_ruleset_id)
  checks='{"type":"required_status_checks","parameters":{"strict_required_status_checks_policy":false,"do_not_enforce_on_create":false,"required_status_checks":[]}}'
  [[ -n "$id" ]] && checks=$(gh api "repos/$REPO/rulesets/$id" | jq -c '.rules[] | select(.type == "required_status_checks")')
  jq -n --argjson checks "$checks" '{
      name: "beta", target: "branch", enforcement: "active",
      conditions: {ref_name: {include: ["refs/heads/beta"], exclude: []}},
      bypass_actors: [{actor_id: 5, actor_type: "RepositoryRole", bypass_mode: "always"}],
      rules: [
        {type: "deletion"}, {type: "non_fast_forward"},
        {type: "pull_request", parameters: {required_approving_review_count: 0, dismiss_stale_reviews_on_push: false,
          require_code_owner_review: false, require_last_push_approval: false, required_review_thread_resolution: false,
          allowed_merge_methods: ["squash", "merge"]}},
        $checks]}' | gh api -X POST "repos/$REPO/rulesets" --input - --silent
  done_ "beta ruleset created"
else
  SKIPPED+=("beta ruleset: Settings → Rules → New branch ruleset for refs/heads/beta")
fi
pause "Press Enter to continue."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Make beta the default branch"
say "New PRs (yours, contributors', Dependabot's) then target beta without anyone choosing."
if [[ "$(gh api "repos/$REPO" -q .default_branch)" == "beta" ]]; then
  done_ "beta is already the default branch"
elif confirm "Make beta the default branch?"; then
  gh repo edit "$REPO" --default-branch beta
  done_ "beta is the default branch"
else
  SKIPPED+=("Default branch: Settings → General → Default branch → beta")
fi
pause "Press Enter to continue."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Limit the npm environment to main and beta"
say "The release job publishes from the \"npm\" environment. Only main and beta may use it."
# 404 until the environment has custom branch policies; gh prints that error body on stdout, so drop it.
policies=$(gh api "repos/$REPO/environments/npm/deployment-branch-policies" -q '[.branch_policies[].name] | sort | join(",")' 2>/dev/null) || policies=""
if [[ "$policies" == "beta,main" ]]; then
  done_ "npm already allows only main and beta"
elif confirm "Restrict the npm environment to the main and beta branches?"; then
  gh api -X PUT "repos/$REPO/environments/npm" --input - --silent <<<'{"deployment_branch_policy":{"protected_branches":false,"custom_branch_policies":true}}'
  for b in main beta; do
    [[ ",$policies," == *",$b,"* ]] || gh api -X POST "repos/$REPO/environments/npm/deployment-branch-policies" -f name="$b" -f type=branch --silent
  done
  done_ "npm environment: main and beta only"
else
  SKIPPED+=("npm environment: Settings → Environments → npm → Deployment branches → main, beta")
fi
pause "Press Enter to continue."

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "npm: bind the Trusted Publisher to the environment"
say "npm should accept a publish only from the npm environment, not from any job in publish.yml."
open_url "https://www.npmjs.com/package/archidocs/access"
step "Sign in if asked. Under Trusted Publisher, edit the GitHub Actions entry."
step "Check: Organization or user chalharb, Repository archidocs, Workflow filename publish.yml."
step "Set Environment name to: npm. Save (npm may ask for 2FA)."
pause "Press Enter once it's saved."

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: delete the old next.archidocs.dev Worker"
say "beta.archidocs.dev replaces it; nothing redirects."
open_url "https://dash.cloudflare.com/?to=/:account/workers/services/view/archidocs-docs-next/production/settings"
step "Settings → scroll to the bottom → Delete. Type the Worker name to confirm."
step "Its next.archidocs.dev Custom Domain goes with it."
step "Then SSL/TLS → Edge Certificates on archidocs.dev: delete a certificate for"
step "next.archidocs.dev if one is listed (Cloudflare doesn't remove it)."
pause "Press Enter when that's done, or to skip it for now."

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Retarget open pull requests to beta"
open_prs=$(gh pr list -R "$REPO" --base main --state open --json number,title,headRefName \
  -q '.[] | select(.headRefName != "beta") | "\(.number)\t\(.title)"')
if [[ -z "$open_prs" ]]; then
  done_ "no open PRs target main"
else
  say "These PRs target main. Unreleased work belongs on beta:"
  while IFS=$'\t' read -r n t; do note "    #$n  $t"; done <<<"$open_prs"
  if confirm "Retarget them all to beta?"; then
    while IFS=$'\t' read -r n _; do gh pr edit "$n" -R "$REPO" --base beta >/dev/null; done <<<"$open_prs"
    done_ "retargeted to beta"
  else
    SKIPPED+=("Retarget open PRs: gh pr edit <n> --base beta")
  fi
fi

finish
say "Next: merge a feat or fix PR into beta. Its Release run publishes X.Y.Z-beta.1; then check:"
step "npm view archidocs dist-tags   (beta: X.Y.Z-beta.1, latest unchanged)"
step "the GitHub Release is marked as a pre-release, and v1 didn't move"
step "curl -sI https://beta.archidocs.dev | grep -i x-robots-tag   (noindex)"
printf '\n'
}

run_wizard "$@"; exit
